#!/usr/bin/env python3
"""Generate the shared typed calibration codec from the retained own003 layout."""
import sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'tools'))
from engine_protocol_legacy import NUMBERS,FLAGS,CURVES,REVISION_OFFSET,TIMING_FIELDS
out=['// Generated by scripts/generate_tuning_wire.py. Preserve historical own003 offsets.', '#pragma once','#include "ecu/engine.hpp"','#include <array>','#include <cstring>','#include <limits>','namespace ecu::tuning {',
 'inline constexpr std::size_t page_bytes=4768,live_bytes=216,chunk_bytes=256;',
 'inline constexpr const char signature[]="ESP32ECU DEV 004 INHIBITED";',
 'inline constexpr const char serial_protocol[]="002";',
 'using Page=std::array<std::uint8_t,page_bytes>;',
 'inline void put_u32(std::uint8_t*p,std::uint32_t v){for(unsigned i=0;i<4;++i)p[i]=std::uint8_t(v>>(8*i));}',
 'inline std::uint32_t get_u32(const std::uint8_t*p){std::uint32_t v=0;for(unsigned i=0;i<4;++i)v|=std::uint32_t(p[i])<<(8*i);return v;}',
 'inline void put_float(std::uint8_t*p,float v){static_assert(sizeof(float)==4&&std::numeric_limits<float>::is_iec559);std::uint32_t u;std::memcpy(&u,&v,4);put_u32(p,u);}',
 'inline float get_float(const std::uint8_t*p){auto u=get_u32(p);float v;std::memcpy(&v,&u,4);return v;}',
 'inline bool reserved_offset(std::size_t n){return (n>=292&&n<512)||n>=4756;}',
 'inline bool revision_offset(std::size_t n){return n>=268&&n<272;}',
 'inline void encode_page(const engine::Tune&t,std::uint32_t origin,Page&p){p.fill(0);']
out.append(' put_u32(p.data(),'+ '|'.join('(std::uint32_t(t.'+k+')<<'+str(i)+')' for i,k in enumerate(FLAGS))+');')
for i,(_,k) in enumerate(NUMBERS):out.append(f' put_float(p.data()+{4+4*i},t.{k});')
offset=4+4*len(NUMBERS)
for k,n in CURVES:out.append(f' for(unsigned i=0;i<{n};++i)put_float(p.data()+{offset}+i*4,t.{k}[i]);');offset+=n*4
assert offset==REVISION_OFFSET
out+=[' put_u32(p.data()+268,origin);',' put_u32(p.data()+272,std::uint32_t(t.strategy));']
for k,offset in TIMING_FIELDS:out.append(f' put_float(p.data()+{offset},t.{k});')
out.append(' for(unsigned i=0;i<4;++i)p[288+i]=t.firing_order[i];')
for k,offset in [('ve',512),('spark',1664),('lambda',2816)]:
 out += [f' for(unsigned i=0;i<16;++i){{put_float(p.data()+{offset}+i*4,t.{k}.rpm[i]);put_float(p.data()+{offset+64}+i*4,t.{k}.load[i]);}}',f' for(unsigned i=0;i<256;++i)put_float(p.data()+{offset+128}+i*4,t.{k}.cells[i]);']
out += [' for(unsigned c=0;c<4;++c){const auto&m=t.cylinder_fuel[c];const auto o=3968+c*192;', '  for(unsigned i=0;i<6;++i){put_float(p.data()+o+i*4,m.rpm[i]);put_float(p.data()+o+24+i*4,m.load[i]);}', '  for(unsigned i=0;i<36;++i){put_float(p.data()+o+48+i*4,m.cells[i]);}put_float(p.data()+4736+c*4,t.cylinder_spark_deg[c]);}', ' put_u32(p.data()+4752,t.cylinder_trims_enabled);','}',
 'inline bool decode_page(const Page&p,std::uint32_t origin,engine::Tune&t){', ' if(!origin||get_u32(p.data()+268)!=origin)return false;', ' for(unsigned n=0;n<page_bytes;++n)if(reserved_offset(n)&&p[n])return false;',f' const auto flags=get_u32(p.data());if(flags>>{len(FLAGS)})return false;']
for i,k in enumerate(FLAGS):out.append(f' t.{k}=flags&(1U<<{i});')
for i,(_,k) in enumerate(NUMBERS):
 if k=='cylinders':out.append(f' if(get_float(p.data()+{4+4*i})!=4){{return false;}}t.cylinders=4;')
 else:out.append(f' t.{k}=get_float(p.data()+{4+4*i});')
offset=4+4*len(NUMBERS)
for k,n in CURVES:out.append(f' for(unsigned i=0;i<{n};++i)t.{k}[i]=get_float(p.data()+{offset}+i*4);');offset+=n*4
out += [' t.revision=origin;const auto strategy=get_u32(p.data()+272);if(strategy>1)return false;t.strategy=engine::Strategy(strategy);']
for k,offset in TIMING_FIELDS:out.append(f' t.{k}=get_float(p.data()+{offset});')
out.append(' for(unsigned i=0;i<4;++i)t.firing_order[i]=p[288+i];')
for k,offset in [('ve',512),('spark',1664),('lambda',2816)]:
 out += [f' for(unsigned i=0;i<16;++i){{t.{k}.rpm[i]=get_float(p.data()+{offset}+i*4);t.{k}.load[i]=get_float(p.data()+{offset+64}+i*4);}}',f' for(unsigned i=0;i<256;++i)t.{k}.cells[i]=get_float(p.data()+{offset+128}+i*4);']
out += [' for(unsigned c=0;c<4;++c){auto&m=t.cylinder_fuel[c];const auto o=3968+c*192;', '  for(unsigned i=0;i<6;++i){m.rpm[i]=get_float(p.data()+o+i*4);m.load[i]=get_float(p.data()+o+24+i*4);}', '  for(unsigned i=0;i<36;++i){m.cells[i]=get_float(p.data()+o+48+i*4);}t.cylinder_spark_deg[c]=get_float(p.data()+4736+c*4);}', ' const auto enabled=get_u32(p.data()+4752);if(enabled>1)return false;t.cylinder_trims_enabled=enabled;', ' return !engine::validate(t);','}',
 '// Update only an owned, already canonical schema3 tree. No global data mutates.', 'template<class Json> bool update_document(Json&j,const engine::Tune&t){', ' if(!j.header(t.revision,engine::strategy_name(t.strategy)))return false;']
for group,k in NUMBERS:out.append(f' if(!j.number("{group}","{k}",t.{k}))return false;')
for k in FLAGS:out.append(f' if(!j.boolean("settings","{k}",t.{k}))return false;')
for k,n in CURVES:out.append(f' if(!j.array("curves","{k}",t.{k}))return false;')
for k in ['ve','spark','lambda']:out.append(f' if(!j.map("{k}",t.{k}))return false;')
for k,_ in TIMING_FIELDS:out.append(f' if(!j.number("timing","{k}",t.{k}))return false;')
out += [' if(!j.array("timing","firing_order",t.firing_order)||!j.boolean("cylinder_trims","enabled",t.cylinder_trims_enabled)||!j.array("cylinder_trims","spark_deg",t.cylinder_spark_deg))return false;', ' for(unsigned i=0;i<4;++i)if(!j.trim(i,t.cylinder_fuel[i]))return false;', ' return true;','}','} // namespace ecu::tuning']
(R/'firmware/include/ecu/tuning_layout.hpp').write_text('\n'.join(out)+'\n')
print('Generated shared own004 single-page typed codec')
